package com.citacloud.app.views; import com.citacloud.app.models.Paciente; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.formlayout.FormLayout; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import com.vaadin.flow.component.textfield.*; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.util.*;
@Route(value="signos-vitales",layout=MainLayout.class) @PageTitle("Signos vitales | CitaCloud") @PermitAll public class SignosVitalesView extends VerticalLayout {public SignosVitalesView(SignosVitalesService service,PacienteService pacientes){TenantUserDetails u=AuthService.getAuthenticatedUser();UUID empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);add(new H2("Signos vitales"),new Paragraph("El IMC se calcula de manera segura en el servidor."));ComboBox<Paciente> paciente=new ComboBox<>("Paciente",empresa==null?List.of():pacientes.listarPorEmpresa(empresa));paciente.setItemLabelGenerator(Paciente::getNombreCompleto);BigDecimalField peso=new BigDecimalField("Peso (kg)");BigDecimalField altura=new BigDecimalField("Altura (m)");BigDecimalField temperatura=new BigDecimalField("Temperatura");IntegerField sistolica=new IntegerField("Presión sistólica");IntegerField diastolica=new IntegerField("Presión diastólica");FormLayout form=new FormLayout(paciente,peso,altura,temperatura,sistolica,diastolica);Button guardar=new Button("Guardar",e->{try{service.registrar(empresa,paciente.getValue().getId(),peso.getValue(),altura.getValue(),temperatura.getValue(),sistolica.getValue(),diastolica.getValue());Notification.show("Signos vitales registrados.");}catch(Exception x){Notification.show(x.getMessage());}});add(form,guardar);}}
